    """Set entity_type on an entity or argument dict, preserving the original key."""
    if source == "entity_list":
        if "entity_type" in obj:
            obj["entity_type"] = new_type
        elif "type" in obj:
            obj["type"] = new_type
        else:
            obj["entity_type"] = new_type
    else:
        obj["entity_type"] = new_type


